const fs = require('fs');
const https = require('https');

// Certificates are generated by gen-certs.sh
const CERT_DIR = process.env.CERT_DIR || __dirname + '/generated';
const SERVER_CERT = process.env.SERVER_CERT || 'server';
const VERBOSE = process.env.VERBOSE === '1';

const ca = fs.readFileSync(CERT_DIR + '/ca.crt');
const PORT = process.env.PORT || 5555;

setTimeout(() => {
https
  .createServer(
    {
      // ...
      requestCert: true,
      rejectUnauthorized: false,
      ca,
      cert: fs.readFileSync(CERT_DIR + '/' + SERVER_CERT + '.pem'),
      key: fs.readFileSync(CERT_DIR + '/' + SERVER_CERT + '-key.pem'),
      // ...
    },
    (req, res) => {
      const cert = req.socket.getPeerCertificate();
      if (VERBOSE) {
        console.log('cert', cert);
      }
     
      if(Object.keys(cert).length > 0 && cert) {
        res.setHeader('Content-Type', 'application/json');
        res.writeHead(200);
        return res.end(JSON.stringify(cert));
      }
      if (!req.client.authorized) {
        res.writeHead(401);
        return res.end('Invalid client certificate authentication.');
      }


      res.writeHead(200);
      res.end('Hello, world!');
    }
  )
  .listen(PORT, '0.0.0.0', () => {
	console.log('Listening on ' + PORT);
  });

}, 3000);